using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.ANM.Anuncios;using GraphApi.Services.ANM.Anuncios;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.ANM.Anuncios{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Anuncios: creación, actualización y eliminación.")]    public class AnunciosMutation    {        [Authorize]        [GraphQLName("createAnuncios")]        [GraphQLDescription("Crea un nuevo Anuncio usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadAnuncios> CreateAnunciosAsync(            [GraphQLDescription("Datos necesarios para crear el Anuncio.")]            clCreateAnuncios objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Anuncio.")]            IAnunciosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateAnuncios(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateAnuncios")]        [GraphQLDescription("Actualiza los campos especificados de un Anuncio existente.")]        public async Task<clReadAnuncios?> UpdateAnunciosAsync(            [GraphQLDescription("Datos del Anuncio a actualizar.")]            clUpdateAnuncios objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Anuncio.")]            IAnunciosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateAnuncios(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteAnuncios")]        [GraphQLDescription("Elimina un Anuncio por su ID.")]        public async Task<bool> delAnunciosAsync(            [GraphQLDescription("ID del Anuncio a eliminar.")]            int nAnunciosID,            [Service]            [GraphQLDescription("Servicio para operaciones de Anuncio.")]            IAnunciosService objService        )        {            return await objService.DeleteAnuncios(nAnunciosID);        }    }}